+		"INSERT INTO users (id, email, password_hash, created_at) VALUES (?, ?, ?, ?)",
+		id, email, passwordHash, now.Format(time.RFC3339Nano))
+	if err != nil {
+		return nil, err
+	}
+	return &store.User{ID: id, Email: email, PasswordHash: passwordHash, CreatedAt: now}, nil
+}
+
+func (s *DB) GetUserByEmail(ctx context.Context, email string) (*store.User, error) {
+	u := &store.User{}
+	var createdAt string
+	err := s.db.QueryRowContext(ctx,
