+	id := newID()
+	now := time.Now().UTC()
+	expires := now.Add(30 * 24 * time.Hour)
+	_, err := s.db.ExecContext(ctx,
+		"INSERT INTO sessions (id, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)",
