+	if err != nil {
+		return nil, err
+	}
+	return &store.Session{ID: id, UserID: userID, CreatedAt: now, ExpiresAt: expires}, nil
+}
+
+func (s *DB) GetSession(ctx context.Context, id string) (*store.Session, error) {
+	sess := &store.Session{}
+	var createdAt, expiresAt string
